using BookStore.Api.Features.Catalog;
using Microsoft.EntityFrameworkCore;

namespace BookStore.Api.Infrastructure;

/// <summary>
/// The single EF Core context. Entity mapping lives next to each entity in its feature folder
/// (IEntityTypeConfiguration) and is discovered here, so features do not edit this file to add mapping.
/// </summary>
public sealed class BookStoreDbContext(DbContextOptions<BookStoreDbContext> options) : DbContext(options)
{
    public DbSet<Book> Books => Set<Book>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.ApplyConfigurationsFromAssembly(typeof(BookStoreDbContext).Assembly);
    }
}
